29	/* :not(.taskbar) keeps this off the taskbar module's active button */
30	#workspaces:not(.taskbar) button.active {
31	    background-image: url('/home/krubics/.config/waybar/assets/pokeball.png');
32	    background-position: center;
33	    background-repeat: no-repeat;
34	    background-size: contain;
35	    background-origin: content-box; /* inset the ball from the accent pill's edges */
36	    background-color: @primary;
37	    color: transparent; /* hides the workspace number behind the pokeball */
38	    padding: 4px 4px;
39	    margin: 4px 0px;
40	    min-width: 20px;
41	    min-height: 20px;
42	    border: 1px solid @outline;
